const now = new Date();
const start = now.toISOString();
const end = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
return [{ json: {
  windowStart: start,
  windowEnd: end,
  baseUrl: ($env.OPENEMR_BASE_URL || 'https://emr.hrthouse.com').replace(/\/$/, ''),
  siteId: $env.OPENEMR_SITE_ID || 'default',
  token: $env.OPENEMR_ACCESS_TOKEN || '',
  reminderWebhook: $env.NOTIFICATION_WEBHOOK_URL || '',
  auditWebhook: $env.AUDIT_WEBHOOK_URL || ''
}}];

const bundle = $json || {};
const entries = Array.isArray(bundle.entry) ? bundle.entry : [];
if (!entries.length) return [];
return entries.map((entry) => {
  const appt = entry.resource || {};
  const participants = Array.isArray(appt.participant) ? appt.participant : [];
  const patientParticipant = participants.find((p) => /Patient\//.test(p?.actor?.reference || '')) || participants[0] || {};
  const providerParticipant = participants.find((p) => /Practitioner\//.test(p?.actor?.reference || '')) || {};
  const patientName = patientParticipant?.actor?.display || patientParticipant?.actor?.reference || appt?.subject?.display || 'Unknown patient';
  const providerName = providerParticipant?.actor?.display || providerParticipant?.actor?.reference || appt?.serviceType?.[0]?.text || 'OpenEMR provider';
  const startTime = appt.start || appt.created || '';
  const reminderText = `Reminder: ${patientName} has an appointment at ${startTime} with ${providerName}.`;
  return { json: { appointment_id: appt.id || entry.fullUrl || '', patient_name: patientName, provider_name: providerName, start_time: startTime, reminder_text: reminderText, reminderWebhook: $('Build Reminder Window').item.json.reminderWebhook, auditWebhook: $('Build Reminder Window').item.json.auditWebhook } };
});
